function formatUserForAppointment(user, userRole, isViewingOwnData = false) {
  if (isViewingOwnData) {
    return {
      id: user.id,
      name: user.name || null,
      email: user.email || null,
      image: user.image || null,
      role: user.role || null,
      employeeCode: user.employeeCode || null
    };
  }
  if (userRole === "doctor") {
    return {
      id: user.id,
      name: user.name || null,
      email: user.email || null,
      image: user.image || null,
      role: user.role || null,
      employeeCode: user.employeeCode || null
    };
  }
  if (user.isAnonymous === true) {
    return {
      id: user.id,
      name: null,
      email: null,
      image: null,
      role: user.role || null,
      employeeCode: user.employeeCode || null
    };
  }
  return {
    id: user.id,
    name: user.name || null,
    email: user.email || null,
    image: user.image || null,
    role: user.role || null,
    employeeCode: user.employeeCode || null
  };
}

