// src/lib/generate-employee-code.ts
function generateEmployeeCodeSuffix() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let code = "";
  for (let i3 = 0;i3 < 6; i3++) {
    const randomIndex = Math.floor(Math.random() * chars.length);
    code += chars[randomIndex];
  }
  return code;
}
async function generateUniqueEmployeeCode(enterpriseCode, maxAttempts = 10) {
  const prisma2 = (await Promise.resolve().then(() => (init_prisma(), exports_prisma))).default;
  for (let attempt = 0;attempt < maxAttempts; attempt++) {
    const suffix = generateEmployeeCodeSuffix();
    const employeeCode = `${enterpriseCode}-${suffix}`;
    const existingUser = await prisma2.user.findFirst({
      where: {
        employeeCode
      }
    });
    if (!existingUser) {
      return employeeCode;
    }
  }
  throw new Error("Failed to generate unique employee code after multiple attempts");
}

