var formatProfessionalExperienceResponse = (professionalExperience) => ({
  id: professionalExperience.id,
  doctorId: professionalExperience.doctorId,
  age_group: professionalExperience.age_group,
  languages: professionalExperience.languages,
  profession: professionalExperience.profession,
  special_interest_area: professionalExperience.special_interest_area,
  createdAt: professionalExperience.createdAt.toISOString(),
  updatedAt: professionalExperience.updatedAt.toISOString()
});
var formatDocumentsResponse = (documents) => ({
  id: documents.id,
  doctorId: documents.doctorId,
  resume: documents.resume,
  medicalLicense: documents.medicalLicense,
  introductionVideo: documents.introductionVideo,
  createdAt: documents.createdAt.toISOString(),
  updatedAt: documents.updatedAt.toISOString()
});
var DOCTOR_PROFILE_ROUTES_HANDLER = {
  createOrUpdate: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const body = c3.req.valid("json");
    try {
      const [professionalExperience, documents] = await Promise.all([
        PROFESSIONAL_EXPERIENCE_SERVICES.createOrUpdate({
          doctorId: doctor2.id,
          age_group: body.professionalExperience.age_group,
          languages: body.professionalExperience.languages,
          profession: body.professionalExperience.profession,
          special_interest_area: body.professionalExperience.special_interest_area
        }),
        DOCUMENTS_SERVICES.createOrUpdate({
          doctorId: doctor2.id,
          resume: body.documents.resume || null,
          medicalLicense: body.documents.medicalLicense || null,
          introductionVideo: body.documents.introductionVideo || null
        })
      ]);
      await prisma_default.user.update({
        where: { id: user.id },
        data: { onboardingStage: "WAITING_FOR_ADMIN" }
      });
      const { createNotificationForUser: createNotificationForUser2, createNotificationForAllAdmins: createNotificationForAllAdmins2, NOTIFICATION_TYPES: NOTIFICATION_TYPES2 } = await Promise.resolve().then(() => (init_notification_helper(), exports_notification_helper));
      await Promise.all([
        createNotificationForUser2(user.id, NOTIFICATION_TYPES2.DOCTOR_ONBOARDING_REQUEST, "Your doctor profile has been submitted and is pending admin approval."),
        createNotificationForAllAdmins2(NOTIFICATION_TYPES2.DOCTOR_ONBOARDING_REQUEST, `New doctor profile submission from ${user.name} is pending approval.`)
      ]);
      return c3.json({
        message: "Doctor profile created or updated successfully",
        success: true,
        data: {
          professionalExperience: formatProfessionalExperienceResponse(professionalExperience),
          documents: formatDocumentsResponse(documents)
        }
      }, OK);
    } catch (error44) {
      if (error44 instanceof HttpError) {
        throw error44;
      }
      if (error44 instanceof Error && error44.message === "Doctor not found") {
        throw new HttpError("Doctor not found", NOT_FOUND);
      }
      throw new HttpError("Failed to create or update doctor profile", INTERNAL_SERVER_ERROR);
    }
  },
  getCurrent: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const [professionalExperience, documents] = await Promise.all([
      PROFESSIONAL_EXPERIENCE_SERVICES.getByDoctorId(doctor2.id),
      DOCUMENTS_SERVICES.getByDoctorId(doctor2.id)
    ]);
    if (!professionalExperience) {
      throw new HttpError("Professional experience not found", NOT_FOUND);
    }
    if (!documents) {
      throw new HttpError("Documents not found", NOT_FOUND);
    }
    return c3.json({
      message: "Doctor profile retrieved successfully",
      success: true,
      data: {
        professionalExperience: formatProfessionalExperienceResponse(professionalExperience),
        documents: formatDocumentsResponse(documents)
      }
    }, OK);
  }
};
