var formatEducationResponse = (education) => ({
  id: education.id,
  doctorId: education.doctorId,
  degree: education.degree,
  startYear: education.startYear.toISOString(),
  endYear: education.endYear?.toISOString() || null,
  document: education.document,
  institution_name: education.institution_name,
  createdAt: education.createdAt.toISOString(),
  updatedAt: education.updatedAt.toISOString()
});
var handleEducationError = (error44) => {
  if (error44 instanceof HttpError) {
    throw error44;
  }
  if (error44 instanceof Error) {
    if (error44.message === "Education not found") {
      throw new HttpError("Education record not found", NOT_FOUND);
    }
    if (error44.message.includes("Unauthorized")) {
      throw new HttpError("Unauthorized: Education does not belong to this doctor", FORBIDDEN);
    }
  }
  throw new HttpError("Operation failed", INTERNAL_SERVER_ERROR);
};
var EDUCATION_ROUTES_HANDLER = {
  bulkCreate: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const { educations } = c3.req.valid("json");
    try {
      const createdEducations = await EDUCATION_SERVICES.bulkCreate({
        doctorId: doctor2.id,
        educations: educations.map((edu) => ({
          degree: edu.degree,
          startYear: new Date(edu.startYear),
          endYear: edu.endYear ? new Date(edu.endYear) : null,
          document: edu.document || null,
          institution_name: edu.institution_name
        }))
      });
      return c3.json({
        message: `Successfully created ${createdEducations.length} education record(s)`,
        success: true,
        data: {
          educations: createdEducations.map(formatEducationResponse)
        }
      }, CREATED);
    } catch (error44) {
      if (error44 instanceof HttpError) {
        throw error44;
      }
      if (error44 instanceof Error && error44.message === "Doctor not found") {
        throw new HttpError("Doctor not found", NOT_FOUND);
      }
      throw new HttpError("Failed to create education records", INTERNAL_SERVER_ERROR);
    }
  },
  getAll: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const educations = await EDUCATION_SERVICES.getAllByDoctorId(doctor2.id);
    return c3.json({
      message: "Education records retrieved successfully",
      success: true,
      data: {
        educations: educations.map(formatEducationResponse)
      }
    }, OK);
  },
  getById: async (c3) => {
    const { id } = c3.req.valid("param");
    const education = await EDUCATION_SERVICES.getById(id);
    if (!education) {
      throw new HttpError("Education record not found", NOT_FOUND);
    }
    return c3.json({
      message: "Education record retrieved successfully",
      success: true,
      data: formatEducationResponse(education)
    }, OK);
  },
  update: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const { id } = c3.req.valid("param");
    const body = c3.req.valid("json");
    try {
      const updatedEducation = await EDUCATION_SERVICES.update({
        id,
        doctorId: doctor2.id,
        degree: body.degree,
        startYear: body.startYear ? new Date(body.startYear) : undefined,
        endYear: body.endYear !== undefined ? body.endYear ? new Date(body.endYear) : null : undefined,
        document: body.document !== undefined ? body.document : undefined,
        institution_name: body.institution_name
      });
      return c3.json({
        message: "Education record updated successfully",
        success: true,
        data: formatEducationResponse(updatedEducation)
      }, OK);
    } catch (error44) {
      handleEducationError(error44);
    }
  },
  delete: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "doctor") {
      throw new HttpError("Only doctors can access this endpoint", FORBIDDEN);
    }
    const doctor2 = await DOCTOR_SERVICES.getByUserId(user.id);
    if (!doctor2) {
      throw new HttpError("Doctor information not found", NOT_FOUND);
    }
    const { id } = c3.req.valid("param");
    try {
      await EDUCATION_SERVICES.delete({
        id,
        doctorId: doctor2.id
      });
      return c3.json({
        message: "Education record deleted successfully",
        success: true
      }, OK);
    } catch (error44) {
      handleEducationError(error44);
    }
  }
};
