init_error();
var extractS3KeyFromUrl3 = (fileUrlOrKey) => {
  try {
    const url2 = new URL(fileUrlOrKey);
    return url2.pathname.startsWith("/") ? url2.pathname.slice(1) : url2.pathname;
  } catch {
    return fileUrlOrKey;
  }
};
var FILES_ROUTES_HANDLER = {
  generateUploadUrl: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    const role3 = user.role;
    const name = user.name;
    const { fileName, fileType } = c3.req.valid("json");
    try {
      const sanitizedFileName = fileName.replace(/[^a-zA-Z0-9.-]/g, "_");
      const extension = fileType.split("/")[1] || "bin";
      const uniqueKey = `${sanitizedFileName}-${Date.now()}.${extension}`;
      const key = `${role3}/${name}/${uniqueKey}`;
      const uploadUrl = await generateUploadUrl(key, 3600);
      const downloadExpiryTime = 7 * 24 * 3600;
      const fileUrl = await generateDownloadUrl(key, downloadExpiryTime);
      const expiresAt = new Date(Date.now() + downloadExpiryTime * 1000).toISOString();
      return c3.json({
        message: "Upload URL generated successfully",
        data: {
          uploadUrl,
          key,
          fileUrl,
          expiresAt
        }
      }, OK);
    } catch (error44) {
      console.error("Error generating upload URL:", error44);
      throw new HttpError("Failed to generate upload URL", INTERNAL_SERVER_ERROR);
    }
  },
  deleteFiles: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    const fileUrls = c3.req.valid("json").fileUrls;
    try {
      const keysToDelete = fileUrls.map((fileUrlOrKey) => extractS3KeyFromUrl3(fileUrlOrKey));
      if (keysToDelete.length === 0) {
        throw new HttpError("No valid file URLs or keys provided", BAD_REQUEST);
      }
      await deleteObjectsFromS3(keysToDelete);
      return c3.json({
        message: `Successfully deleted ${keysToDelete.length} file(s)`,
        deletedFiles: keysToDelete
      }, OK);
    } catch (error44) {
      console.error("Error deleting files:", error44);
      if (error44 instanceof HttpError) {
        throw error44;
      }
      throw new HttpError("Failed to delete files", INTERNAL_SERVER_ERROR);
    }
  },
  getSignedUrl: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    const { key, expiresIn } = c3.req.valid("json");
    try {
      const s3Key = extractS3KeyFromUrl3(key);
      const expirySeconds = expiresIn || 3600;
      const signedUrl = await generateDownloadUrl(s3Key, expirySeconds);
      const expiresAt = new Date(Date.now() + expirySeconds * 1000).toISOString();
      return c3.json({
        signedUrl,
        expiresIn: expirySeconds,
        expiresAt
      }, OK);
    } catch (error44) {
      console.error("Error generating signed URL:", error44);
      throw new HttpError("Failed to generate signed URL", INTERNAL_SERVER_ERROR);
    }
  }
};
