var USER_QUERY_ROUTES_HANDLER = {
  create: async (c3) => {
    const user = c3.get("user");
    const { message: message2, organizationName, organizationEmail } = c3.req.valid("json");
    const userQuery = await USER_QUERY_SERVICES.create({
      message: message2,
      organizationName,
      organizationEmail,
      userId: user?.id || null
    });
    return c3.json({
      message: "User query created successfully",
      success: true,
      data: formatUserQueryResponse(userQuery)
    }, CREATED);
  },
  getAll: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin" && user.role !== "team_admin") {
      throw new HttpError("Forbidden - Admin or Team Member only", FORBIDDEN);
    }
    const query = c3.req.valid("query");
    const filters = {
      page: query.page ? parseInt(query.page, 10) : 1,
      limit: query.limit ? parseInt(query.limit, 10) : 10,
      search: query.search
    };
    const result = await USER_QUERY_SERVICES.getAll(filters);
    return c3.json({
      message: "User queries retrieved successfully",
      success: true,
      data: {
        userQueries: result.userQueries.map(formatUserQueryResponse),
        pagination: result.pagination
      }
    }, OK);
  },
  getById: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin" && user.role !== "team_admin") {
      throw new HttpError("Forbidden - Admin or Team Member only", FORBIDDEN);
    }
    const { id } = c3.req.valid("param");
    const userQuery = await USER_QUERY_SERVICES.getById(id);
    if (!userQuery) {
      throw new HttpError("User query not found", NOT_FOUND);
    }
    return c3.json({
      message: "User query retrieved successfully",
      success: true,
      data: formatUserQueryResponse(userQuery)
    }, OK);
  },
  delete: async (c3) => {
    const user = c3.get("user");
    if (!user) {
      throw new HttpError("Unauthorized", UNAUTHORIZED);
    }
    if (user.role !== "admin" && user.role !== "team_admin") {
      throw new HttpError("Forbidden - Admin or Team Member only", FORBIDDEN);
    }
    const { id } = c3.req.valid("param");
    try {
      await USER_QUERY_SERVICES.delete(id);
      return c3.json({
        message: "User query deleted successfully",
        success: true
      }, OK);
    } catch (error44) {
      if (error44 instanceof Error && "code" in error44 && error44.code === "P2025") {
        throw new HttpError("User query not found", NOT_FOUND);
      }
      throw error44;
    }
  }
};
