function configureOpenAPI(app) {
  app.doc("/doc", {
    openapi: "3.0.0",
    info: {
      version: "1",
      title: "API Docs"
    }
  });
  app.get("/reference", Scalar({
    theme: "kepler",
    layout: "modern",
    url: "/doc",
    showSidebar: true,
    hideModels: true,
    hideDownloadButton: false,
    hideTestRequestButton: false,
    searchHotKey: "k",
    hiddenClients: true,
    hideClientButton: true,
    defaultHttpClient: {
      targetKey: "js",
      clientKey: "fetch"
    },
    authentication: {
      preferredSecurityScheme: "bearerAuth"
    }
  }));
}

// src/services/chat.ts
init_notification_helper();
init_prisma();
var CHAT_SERVICES = {
  verifyAppointmentAccess: async (appointmentId, userId) => {
    const appointment = await prisma_default.appointment.findFirst({
      where: {
        id: appointmentId,
        OR: [{ doctorId: userId }, { patientId: userId }]
      }
    });
    return !!appointment;
  },
  createMessage: async (data) => {
    const hasAccess = await CHAT_SERVICES.verifyAppointmentAccess(data.appointmentId, data.senderId);
    if (!hasAccess) {
      throw new Error("User does not have access to this appointment");
    }
    const appointment = await prisma_default.appointment.findUnique({
      where: { id: data.appointmentId },
      select: {
        id: true,
        doctorId: true,
        patientId: true,
        doctor: {
          select: {
            id: true,
            name: true
          }
        },
        patient: {
          select: {
            id: true,
            name: true
          }
        }
      }
    });
    if (!appointment) {
      throw new Error("Appointment not found");
    }
    if (appointment.doctorId !== data.senderId) {
      throw new Error("Only doctors can send messages. Patients can only view messages.");
    }
    const message2 = await prisma_default.appointmentChat.create({
      data: {
        appointmentId: data.appointmentId,
        senderId: data.senderId,
        content: data.content || null,
        messageType: data.messageType || "TEXT",
        fileUrl: data.fileUrl,
        fileName: data.fileName,
        fileSize: data.fileSize,
        isFromDoctor: true
      },
      include: {
        sender: {
          select: {
            id: true,
            name: true,
            email: true,
            image: true,
            role: true
          }
        }
      }
    });
    const recipientId = data.senderId === appointment.doctorId ? appointment.patientId : appointment.doctorId;
    const senderName = data.senderId === appointment.doctorId ? appointment.doctor.name : appointment.patient.name;
    if (recipientId) {
      const messagePreview = data.content ? data.content.length > 50 ? `${data.content.substring(0, 50)}...` : data.content : data.messageType === "IMAGE" ? "Sent an image" : data.messageType === "FILE" ? `Sent a file: ${data.fileName || "file"}` : "Sent a message";
      const FRONTEND_URL2 = Bun.env.FRONTEND_URL || "https://pathcourse.hasseebmayo.com";
      const notificationUrl = `${FRONTEND_URL2}/patient/session/${data.appointmentId}?tab=chat`;
      await createNotificationForUser(recipientId, NOTIFICATION_TYPES.MESSAGE_RECEIVED_APPOINTMENT, `${senderName}: ${messagePreview}`, data.appointmentId, notificationUrl);
    }
    return {
      id: message2.id,
      content: message2.content,
      messageType: message2.messageType,
      fileUrl: message2.fileUrl,
      fileName: message2.fileName,
      fileSize: message2.fileSize,
      isDelivered: message2.isDelivered,
      isRead: message2.isRead,
      createdAt: message2.createdAt,
      updatedAt: message2.updatedAt,
      sender: message2.sender
    };
  },
  getMessages: async (filters, userId) => {
    const { appointmentId, page = 1, limit = 50, before } = filters;
    const hasAccess = await CHAT_SERVICES.verifyAppointmentAccess(appointmentId, userId);
    if (!hasAccess) {
      throw new Error("User does not have access to this appointment");
    }
    const skip = (page - 1) * limit;
    const whereClause = {
      appointmentId
    };
    if (before) {
      whereClause.createdAt = {
        lt: before
      };
    }
    const total = await prisma_default.appointmentChat.count({
      where: whereClause
    });
    const messages = await prisma_default.appointmentChat.findMany({
      where: whereClause,
      include: {
        sender: {
          select: {
            id: true,
            name: true,
            email: true,
            image: true,
            role: true
          }
        }
      },
      orderBy: {
        createdAt: "desc"
      },
      skip,
      take: limit
    });
    const totalPages = Math.ceil(total / limit);
    const formattedMessages = messages.map((message2) => ({
      id: message2.id,
      content: message2.content,
      messageType: message2.messageType,
      fileUrl: message2.fileUrl,
      fileName: message2.fileName,
      fileSize: message2.fileSize,
      isDelivered: message2.isDelivered,
      isRead: message2.isRead,
      createdAt: message2.createdAt,
      updatedAt: message2.updatedAt,
      sender: message2.sender
    }));
    return {
      messages: formattedMessages,
      pagination: {
        page,
        limit,
        total,
        totalPages,
        hasNextPage: page < totalPages,
        hasPreviousPage: page > 1
      }
    };
  },
  markMessagesAsRead: async (messageIds, userId) => {
    await prisma_default.appointmentChat.updateMany({
      where: {
        id: {
          in: messageIds
        },
        appointment: {
          OR: [{ doctorId: userId }, { patientId: userId }]
        }
      },
      data: {
        isRead: true
      }
    });
  },
  getUnreadCount: async (appointmentId, userId) => {
    const hasAccess = await CHAT_SERVICES.verifyAppointmentAccess(appointmentId, userId);
    if (!hasAccess) {
      throw new Error("User does not have access to this appointment");
    }
    const count = await prisma_default.appointmentChat.count({
      where: {
        appointmentId,
        senderId: {
          not: userId
        },
        isRead: false
      }
    });
    return count;
  },
  createUserSession: async (userId, appointmentId, socketId) => {
    await prisma_default.userSession.upsert({
      where: {
        socketId
      },
      create: {
        userId,
        appointmentId,
        socketId,
        isOnline: true,
        lastSeen: new Date
      },
      update: {
        isOnline: true,
        lastSeen: new Date
      }
    });
  },
  updateUserSession: async (socketId, isOnline) => {
    await prisma_default.userSession.updateMany({
      where: {
        socketId
      },
      data: {
        isOnline,
        lastSeen: new Date
      }
    });
  },
  removeUserSession: async (socketId) => {
    await prisma_default.userSession.deleteMany({
      where: {
        socketId
      }
    });
  },
  getOnlineUsers: async (appointmentId) => {
    const sessions = await prisma_default.userSession.findMany({
      where: {
        appointmentId,
        isOnline: true
      },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            role: true
          }
        }
      }
    });
    return sessions.map((session) => ({
      userId: session.userId,
      name: session.user.name,
      role: session.user.role,
      lastSeen: session.lastSeen
    }));
  },
  isAppointmentChatActive: async (appointmentId) => {
    const appointment = await prisma_default.appointment.findUnique({
      where: { id: appointmentId },
      select: {
        status: true,
        chatroomExpiry: true
      }
    });
    if (!appointment) {
      return false;
    }
    if (appointment.status !== "BOOKED" && appointment.status !== "COMPLETED") {
      return false;
    }
    if (appointment.chatroomExpiry && appointment.chatroomExpiry < new Date) {
      return false;
    }
    return true;
  },
  deleteOldMessages: async (beforeDate) => {
    const result = await prisma_default.appointmentChat.deleteMany({
      where: {
        createdAt: {
          lt: beforeDate
        }
      }
    });
    return result.count;
  },
  getMessageById: async (messageId, userId) => {
    const message2 = await prisma_default.appointmentChat.findUnique({
      where: { id: messageId },
      include: {
        sender: {
          select: {
            id: true,
            name: true,
            email: true,
            image: true,
            role: true
          }
        },
        appointment: {
          select: {
            doctorId: true,
            patientId: true
          }
        }
      }
    });
    if (!message2) {
      return null;
    }
    const hasAccess = message2.appointment.doctorId === userId || message2.appointment.patientId === userId;
    if (!hasAccess) {
      throw new Error("User does not have access to this message");
    }
    return {
      id: message2.id,
      content: message2.content,
      messageType: message2.messageType,
      fileUrl: message2.fileUrl,
      fileName: message2.fileName,
      fileSize: message2.fileSize,
      isDelivered: message2.isDelivered,
      isRead: message2.isRead,
      createdAt: message2.createdAt,
      updatedAt: message2.updatedAt,
      sender: message2.sender
    };
  }
};

// src/sockets/chat-socket.ts
function configureChatSocket(io2) {
  io2.on("connection", (socket) => {
    console.log("Client connected:", socket.id);
    socket.on("join-appointment", async (data) => {
      console.log("Join appointment data:", data);
      try {
        const { appointmentId, userId, role: role3 } = data;
        const hasAccess = await CHAT_SERVICES.verifyAppointmentAccess(appointmentId, userId);
        console.log("Has access:", hasAccess);
        if (!hasAccess) {
          socket.emit("error", { message: "Access denied to appointment" });
          return;
        }
        const isActive = await CHAT_SERVICES.isAppointmentChatActive(appointmentId);
        if (!isActive) {
          socket.emit("error", { message: "Chat is not active for this appointment" });
          return;
        }
        socket.userId = userId;
        socket.appointmentId = appointmentId;
        socket.role = role3;
        await socket.join(`appointment-${appointmentId}`);
        await CHAT_SERVICES.createUserSession(userId, appointmentId, socket.id);
        socket.emit("connected", {
          socketId: socket.id,
          appointmentId,
          userId,
          timestamp: new Date().toISOString()
        });
        socket.to(`appointment-${appointmentId}`).emit("user-joined", {
          userId,
          role: role3,
          timestamp: new Date().toISOString()
        });
        const onlineUsers = await CHAT_SERVICES.getOnlineUsers(appointmentId);
        socket.emit("online-users", { users: onlineUsers });
        console.log(`User ${userId} joined appointment ${appointmentId}`);
      } catch (error44) {
        console.error("Error joining appointment:", error44);
        socket.emit("error", { message: "Failed to join appointment" });
      }
    });
    socket.on("send-message", async (data) => {
      try {
        if (!socket.userId || !socket.appointmentId) {
          socket.emit("error", {
            message: "User not in any appointment. Please join an appointment first using join-appointment event."
          });
          return;
        }
        if (socket.role !== "doctor") {
          socket.emit("error", {
            message: "Only doctors can send messages. Patients can only view messages."
          });
          return;
        }
        if (!data.content && !data.fileUrl) {
          socket.emit("error", { message: "Message must have content or file" });
          return;
        }
        const savedMessage = await CHAT_SERVICES.createMessage({
          appointmentId: socket.appointmentId,
          senderId: socket.userId,
          content: data.content,
          messageType: data.messageType || "TEXT",
          fileUrl: data.fileUrl,
          fileName: data.fileName,
          fileSize: data.fileSize
        });
        io2.to(`appointment-${socket.appointmentId}`).emit("new-message", savedMessage);
      } catch (error44) {
        console.error("Error sending message:", error44);
        socket.emit("error", { message: "Failed to send message" });
      }
    });
    socket.on("typing-start", () => {
      if (socket.userId && socket.appointmentId) {
        socket.to(`appointment-${socket.appointmentId}`).emit("user-typing", {
          userId: socket.userId,
          isTyping: true,
          timestamp: new Date().toISOString()
        });
      }
    });
    socket.on("typing-stop", () => {
      if (socket.userId && socket.appointmentId) {
        socket.to(`appointment-${socket.appointmentId}`).emit("user-stopped-typing", {
          userId: socket.userId,
          isTyping: false,
          timestamp: new Date().toISOString()
        });
      }
    });
    socket.on("mark-read", async (data) => {
      try {
        if (!socket.userId || !socket.appointmentId) {
          socket.emit("error", {
            message: "User not in any appointment. Please join an appointment first using join-appointment event."
          });
          return;
        }
        if (!data.messageIds || !Array.isArray(data.messageIds)) {
          return;
        }
        await CHAT_SERVICES.markMessagesAsRead(data.messageIds, socket.userId);
        socket.to(`appointment-${socket.appointmentId}`).emit("messages-read", {
          messageIds: data.messageIds,
          readBy: socket.userId,
          timestamp: new Date().toISOString()
        });
      } catch (error44) {
        console.error("Error marking messages as read:", error44);
        socket.emit("error", { message: "Failed to mark messages as read" });
      }
    });
    socket.on("ping", () => {
      socket.emit("pong", { timestamp: new Date().toISOString() });
    });
    socket.on("disconnect", async () => {
      try {
        if (socket.userId && socket.appointmentId) {
          await CHAT_SERVICES.updateUserSession(socket.id, false);
          socket.to(`appointment-${socket.appointmentId}`).emit("user-left", {
            userId: socket.userId,
            timestamp: new Date().toISOString()
          });
          console.log(`User ${socket.userId} disconnected from appointment ${socket.appointmentId}`);
        }
      } catch (error44) {
        console.error("Error handling disconnect:", error44);
      }
    });
    socket.on("error", (error44) => {
      console.error("Socket error:", error44);
    });
  });
}

// src/index.ts
var io2 = new Server2({
  cors: {
    origin: ORIGINS,
    credentials: true,
    methods: ["GET", "POST"]
  },
  transports: ["websocket", "polling"],
  allowEIO3: true
});
var engine = new Server;
io2.bind(engine);
configureChatSocket(io2);
var app = createApp();
app.use("*", cors({
  origin: ORIGINS,
  allowHeaders: [
    "Content-Type",
    "Authorization",
    "X-Requested-With",
    "Accept",
    "Origin",
    "Cookie",
    "Set-Cookie"
  ],
  allowMethods: ["POST", "GET", "OPTIONS", "DELETE", "PUT", "PATCH"],
  exposeHeaders: ["Content-Length", "Set-Cookie"],
  maxAge: 86400,
  credentials: true
}));
app.use("*", async (c3, next) => {
  const session = await auth.api.getSession({ headers: c3.req.raw.headers });
  if (!session) {
    c3.set("user", null);
    c3.set("session", null);
    return next();
  }
  c3.set("user", session.user);
  c3.set("session", session.session);
  return next();
});
registerRoutes(app);
app.on(["POST", "GET"], "/api/auth/*", (c3) => {
  return auth.handler(c3.req.raw);
});
configureOpenAPI(app);
doctorConnectionTracker.startStaleConnectionChecker(async (userId) => {
  try {
    await DOCTOR_SERVICES.handleDisconnection(userId);
    console.log(`Doctor ${userId} disconnected - availability set to unavailable`);
  } catch (error44) {
    console.error(`Error handling disconnection for doctor ${userId}:`, error44);
  }
});
appointmentNoShowCron.start();
console.log("Auth reference available at http://localhost:8080/api/auth/reference");
console.log("API reference available at http://localhost:8080/reference");
console.log("Socket.IO server configured for real-time chat");
console.log("Doctor connection tracker started - checking for stale connections every 15 seconds");
console.log("Appointment no-show cron job started - checking every 5 minutes for appointments past 20-minute mark");
var { websocket } = engine.handler();
serve({
  port: Bun.env.PORT_NO || 3000,
  fetch(req, server) {
    const url2 = new URL(req.url);
    if (url2.pathname.startsWith("/socket.io/")) {
      try {
        return engine.handleRequest(req, server);
      } catch (error44) {
        console.error("[Socket.IO] Error handling request:", error44);
        return new Response("Socket.IO error", { status: 500 });
      }
    }
    return app.fetch(req, server);
  },
  websocket
});
console.log(`Server running on port ${Bun.env.PORT_NO || 3000}`);
console.log(`Socket.IO available at ws://localhost:${Bun.env.PORT_NO || 3000}/socket.io/`);
